"""Preserve supplied mutant zombie pose arithmetic in a native client adapter."""
import re
from recover_creature_models import INPUT, ROOT, normalized, body

def main():
    source=normalized(next((INPUT/'mutants').rglob('MutantZombieModel.java')).read_text())
    aliases={field:children[-1] for field,expr in re.findall(r'this\.(\w+) = ([^;]*getChild[^;]+);',source) if (children:=re.findall(r'getChild\((?:\(String\))?"([^"\n]+)"\)',expr))}
    methods=[]
    for name in ['animateMelee','animateRoar']:
        code=body(source,r'private void '+name+r'\(')
        for field,bone in aliases.items():code=re.sub(r'\bthis\.'+re.escape(field)+r'\b','parts.get("'+bone+'")',code)
        code=code.replace('state.animationTime','state.actionTime').replace('Animator.addRotationAngle','addRotation')
        if 'this.' in code:raise ValueError('Unbound pose field in '+name)
        methods.append('    private static void '+name+'(RecoveredWildlifeRenderer.State state, Map<String, ModelPart> parts) {\n'+code+'\n    }')
    out=ROOT/'src/client/java/io/github/jimbozoomer/jugcraft/client/RecoveredMutantPoses.java'
    out.write_text('package io.github.jimbozoomer.jugcraft.client;\n\nimport java.util.Map;\nimport net.minecraft.client.model.geom.ModelPart;\nimport net.minecraft.util.Mth;\n\n/** Supplied MutantZombieModel arithmetic; generated by tools/recover_mutant_poses.py. */\nfinal class RecoveredMutantPoses {\n    static void apply(String model, RecoveredWildlifeRenderer.State state, Map<String, ModelPart> parts) {\n        if (!model.equals("recovered/mutants_mutantzombiemodel") || state.actionTime < 0) return;\n        if (state.action.equals("slam_ground")) animateMelee(state,parts);\n        if (state.action.equals("roar")) animateRoar(state,parts);\n    }\n    private static void addRotation(ModelPart part,float x,float y,float z){part.xRot+=x;part.yRot+=y;part.zRot+=z;}\n'+ '\n'.join(methods)+'\n}\n')
if __name__=='__main__':main()
